import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as d,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"BMAD Method","description":"AI 驱动的敏捷开发框架：Analysis → Planning → Solutioning → Implementation 四阶段、三种规划路径与专用 Agent 工作流速查。","frontmatter":{"title":"BMAD Method","description":"AI 驱动的敏捷开发框架：Analysis → Planning → Solutioning → Implementation 四阶段、三种规划路径与专用 Agent 工作流速查。","domain":"tech","tags":["tech","methodology","legacy","bmad","agile"],"navOrder":86,"topicId":"methodology-bmad","layer":"appendix","status":"legacy","nodeType":"resource","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/methodology/bmad-methodology.md","filePath":"zh/tech/appendices/methodology/bmad-methodology.md","lastUpdated":1791166440000}'),r={name:"zh/tech/appendices/methodology/bmad-methodology.md"};function s(i,t,n,h,c,l){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="bmad-method" tabindex="-1">BMAD Method <a class="header-anchor" href="#bmad-method" aria-label="Permalink to &quot;BMAD Method&quot;">​</a></h1><blockquote><p>原文: <a href="https://github.com/bmad-code-org/BMAD-METHOD" target="_blank" rel="noreferrer">https://github.com/bmad-code-org/BMAD-METHOD</a> ｜ 文档: <a href="https://docs.bmad-method.org" target="_blank" rel="noreferrer">https://docs.bmad-method.org</a> ｜ MIT 开源</p></blockquote><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><strong>BMad Method</strong> 是一个 AI 驱动的敏捷开发框架：从创意构思、规划到 Agent 实现，覆盖整个软件开发流程。核心理念：传统 AI 工具替你思考、产生平均水平的成果；BMad agents 与引导式工作流扮演<strong>专家协作者</strong>，引导你通过结构化流程发挥最佳思维。</p><h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>说明</th></tr></thead><tbody><tr><td>Scale-Domain-Adaptive</td><td>根据项目复杂度自动调整规划深度</td></tr><tr><td>Structured Workflows</td><td>基于敏捷最佳实践的分析/规划/架构/实现工作流</td></tr><tr><td>Specialized Agents</td><td>12+ 领域专家（PM、架构师、开发者、UX 等）</td></tr><tr><td>Party Mode</td><td>多个 agent 角色同堂协作讨论</td></tr><tr><td>Complete Lifecycle</td><td>头脑风暴到部署全生命周期</td></tr></tbody></table><h2 id="四阶段流程与三种规划路径" tabindex="-1">四阶段流程与三种规划路径 <a class="header-anchor" href="#四阶段流程与三种规划路径" aria-label="Permalink to &quot;四阶段流程与三种规划路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>名称</th><th>内容</th></tr></thead><tbody><tr><td>1</td><td>Analysis</td><td>头脑风暴、研究、产品简报或 PRFAQ（可选）</td></tr><tr><td>2</td><td>Planning</td><td>创建需求文档（PRD 或 spec）</td></tr><tr><td>3</td><td>Solutioning</td><td>设计架构（BMad Method/Enterprise 专用）</td></tr><tr><td>4</td><td>Implementation</td><td>按 epic 逐个构建，story 逐个实施</td></tr></tbody></table><table tabindex="0"><thead><tr><th>路径</th><th>适用场景</th><th>产出文档</th></tr></thead><tbody><tr><td><strong>Quick Flow</strong></td><td>Bug 修复、简单 feature、明确范围（1-15 stories）</td><td>仅 Tech-spec</td></tr><tr><td><strong>BMad Method</strong></td><td>产品、平台、复杂 feature（10-50+ stories）</td><td>PRD + Architecture + UX</td></tr><tr><td><strong>Enterprise</strong></td><td>合规、多租户系统（30+ stories）</td><td>+ Security + DevOps</td></tr></tbody></table><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bmad-method</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>环境要求 Node.js v20+ / Python 3.10+ / uv。安装后创建 <code>_bmad/</code>（agents、工作流、任务、配置）与 <code>_bmad-output/</code>（产出物：PRD.md、architecture.md、epics/、sprint-status.yaml）。可与 Claude Code、Cursor、Codex CLI 等任何支持自定义系统提示的 AI 编码助手集成。</p><p><strong>BMad-Help</strong> 是最快上手方式：在 AI IDE 中调用 <code>bmad-help</code>（可带问题），它会检查项目现状、展示选项、推荐下一步。</p><h2 id="实施循环" tabindex="-1">实施循环 <a class="header-anchor" href="#实施循环" aria-label="Permalink to &quot;实施循环&quot;">​</a></h2><p>每个 story 重复（每次新 chat）：DEV agent 运行 <code>bmad-create-story</code> → <code>bmad-dev-story</code> 实施 → <code>bmad-code-review</code> 质量验证。完成后 <code>bmad-retrospective</code> 复盘。</p><p>常用工作流：<code>bmad-create-prd</code>（PRD）、<code>bmad-create-architecture</code>（架构）、<code>bmad-create-epics-and-stories</code>（拆分）、<code>bmad-check-implementation-readiness</code>（就绪检查）、<code>bmad-sprint-planning</code>（冲刺）。</p><p>官方模块：BMM 核心框架（34+ 工作流）、BMad Builder（自定义 agents）、Test Architect（基于风险的测试）、Game Dev Studio、Creative Intelligence Suite。</p><h2 id="与主线的关系" tabindex="-1">与主线的关系 <a class="header-anchor" href="#与主线的关系" aria-label="Permalink to &quot;与主线的关系&quot;">​</a></h2><p>BMAD 的「结构化规划 → 按 story 实施 → 代码评审门」与主线 <a href="/zh/tech/06-agent-systems/recovery-hitl.html">恢复与人工批准</a>（审批点）、<a href="/zh/tech/08-production/testing.html">测试</a>（质量门）同构；其 Agent 角色分工可对照 <a href="/zh/tech/06-agent-systems/multi-agent.html">多 Agent 系统</a> 阅读。作为框架选型时注意：它解决的是「流程结构化」，你的工程判断仍是决定性变量。</p>',19)])])}const y=e(r,[["render",s]]);export{u as __pageData,y as default};
